// Artículo a promocionar esta semana. Cambia los valores o conéctalo a tu lista de contenidos.
return [{ json: {
  titulo: "Mejor robot aspirador 2026: comparativa y guía",
  url: "https://TU-DOMINIO.es/mejor-robot-aspirador-2026.html",
  gancho: "Te enseñamos cuál acierta según tu casa, mascotas y presupuesto — sin tecnicismos."
} }];

// Genera el copy para cada red a partir del artículo.
const a = $input.first().json;
const hashtags = "#domotica #casainteligente #smarthome #robotaspirador";
const posts = {
  instagram: `${a.titulo} 🏠

${a.gancho}

Guía completa en el enlace de la bio 👆

${hashtags}`,
  facebook:  `${a.titulo}

${a.gancho}

👉 ${a.url}`,
  twitter:   `${a.titulo} 🏠
${a.gancho}
${a.url}`
};
// IMPORTANTE (Amazon): el link de afiliado va dentro de la web, NO directo en el post.
return Object.entries(posts).map(([red, texto]) => ({ json: { red, texto, url: a.url } }));
